from rdkit import Chem
import numpy as np
from collections import Counter
m=Chem.MolFromMolFile('structure.mol',sanitize=False,removeHs=False)
lines=open('xtbopt.xyz').read().splitlines();p=np.array([list(map(float,l.split()[1:])) for l in lines[2:]])
print('Composition',Counter(l.split()[0] for l in lines[2:]))
print('Sb bonds')
for i in [1,2,3,4,39,45,51]:print(i,round(np.linalg.norm(p[0]-p[i]),4))
print('Core ring and C=N distances')
for a,b in [(1,5),(2,6),(5,6),(6,7),(7,8),(8,9),(9,10),(10,5)]:print(a,b,round(np.linalg.norm(p[a]-p[b]),3))
print('Long bonds')
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();d=np.linalg.norm(p[i]-p[j]);
 if 0 not in [i,j] and d>1.7:print(i,j,d)
print('Short nonbonds')
for i in range(len(p)):
 for j in range(i):
  d=np.linalg.norm(p[i]-p[j])
  if d<1.3 and not m.GetBondBetweenAtoms(i,j):print(i,j,d)
# Save standard XYZ with one-line description
lines[1]='C52H59N2O2Sb; seven-coordinate antimony complex; GFN2-xTB optimized; coordinates in angstroms'
open('answer.xyz','w').write('\n'.join(lines)+'\n')
